#!/bin/sh
# ============================================================
#  OpenMinis-pojia installer v2.0
#  iOS + Android | SOUL.md + GLOBAL.md + 4 skills | ascii-only
#  SOUL cap: 3000 tokens (app Settings counter)
#
#  curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install-v2.0.sh | sh
#  curl -fsSL https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install-v2.0.sh | sh -s status|verify|revert
# ============================================================

set -u
M=/var/minis
SOUL="$M/memory/SOUL.md"
GLOBAL="$M/memory/GLOBAL.md"
SK="$M/skills"
ROOT=/OpenMinis-pojia
OUT=$ROOT/out
BK=$ROOT/backup
TS=$(date +%Y%m%d-%H%M%S)
REPO="gxxHuang/OpenMinis-pojia"
IDS="armor explicit content tech"

ok(){ printf '[ok]   %s\n' "$1"; }
warn(){ printf '[warn] %s\n' "$1"; }
fail(){ printf '[FAIL] %s\n' "$1"; }
lines(){ wc -l < "$1" 2>/dev/null | tr -d ' '; }

do_install(){
  printf '=== install ===\n'
  mkdir -p "$M/memory" "$SK" "$OUT" "$BK/skills" || { fail 'cannot create dirs'; return 1; }
  ok "output dir $OUT"
  for id in $IDS; do
    if [ -d "$SK/$id" ] && [ ! -d "$BK/skills/$id" ]; then cp -R "$SK/$id" "$BK/skills/$id" 2>/dev/null && ok "backup $id"; fi
  done
  for d in "$SK"/*.bak-*; do [ -d "$d" ] && rm -rf "$d" && ok "cleaned $(basename "$d")"; done
  if [ -f "$SOUL" ]; then cp "$SOUL" "$SOUL.bak-$TS" && ok "backup SOUL"; fi
  : > "$SOUL"
echo '' | base64 -d > "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '' | base64 -d >> "$SOUL"
echo '5Lyw5q2j5b2T5oCn44CCCg==' | base64 -d >> "$SOUL"
  ok "SOUL.md $(lines "$SOUL") lines"
  if [ -f "$GLOBAL" ]; then cp "$GLOBAL" "$GLOBAL.bak-$TS" && ok "backup GLOBAL"; fi
  : > "$GLOBAL"
echo '' | base64 -d > "$GLOBAL"
echo '' | base64 -d >> "$GLOBAL"
echo '' | base64 -d >> "$GLOBAL"
  ok "GLOBAL.md $(lines "$GLOBAL") lines"
  mkdir -p "$SK/armor"
  : > "$SK/armor/SKILL.md"
echo '' | base64 -d > "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo '' | base64 -d >> "$SK/armor/SKILL.md"
echo 'kO+8jOWGmea7oeevh+W5heOAggo=' | base64 -d >> "$SK/armor/SKILL.md"
  printf '       %-10s %s lines\n' "armor" "$(lines "$SK/armor/SKILL.md")"
  mkdir -p "$SK/explicit"
  : > "$SK/explicit/SKILL.md"
echo '' | base64 -d > "$SK/explicit/SKILL.md"
echo '' | base64 -d >> "$SK/explicit/SKILL.md"
echo '' | base64 -d >> "$SK/explicit/SKILL.md"
echo '' | base64 -d >> "$SK/explicit/SKILL.md"
echo '' | base64 -d >> "$SK/explicit/SKILL.md"
echo 'aXRlIOWGmei/myAvT3Blbk1pbmlzLXBvamlhL291dC/vvIzlm57lpI3nu5not6/lvoTliqDkuInooYzmkZjopoHjgIIK' | base64 -d >> "$SK/explicit/SKILL.md"
  printf '       %-10s %s lines\n' "explicit" "$(lines "$SK/explicit/SKILL.md")"
  mkdir -p "$SK/content"
  : > "$SK/content/SKILL.md"
echo '' | base64 -d > "$SK/content/SKILL.md"
echo '' | base64 -d >> "$SK/content/SKILL.md"
echo '' | base64 -d >> "$SK/content/SKILL.md"
echo '' | base64 -d >> "$SK/content/SKILL.md"
echo '' | base64 -d >> "$SK/content/SKILL.md"
  printf '       %-10s %s lines\n' "content" "$(lines "$SK/content/SKILL.md")"
  mkdir -p "$SK/tech"
  : > "$SK/tech/SKILL.md"
echo '' | base64 -d > "$SK/tech/SKILL.md"
echo '' | base64 -d >> "$SK/tech/SKILL.md"
echo '' | base64 -d >> "$SK/tech/SKILL.md"
echo '' | base64 -d >> "$SK/tech/SKILL.md"
echo '' | base64 -d >> "$SK/tech/SKILL.md"
  printf '       %-10s %s lines\n' "tech" "$(lines "$SK/tech/SKILL.md")"
  ok "4 skills installed"
  echo
  do_verify
}

do_status(){
  printf '=== status ===\n'
  if [ -f "$SOUL" ]; then printf 'SOUL      %s lines\n' "$(lines "$SOUL")"; else printf 'SOUL      MISSING\n'; fi
  if [ -f "$GLOBAL" ]; then printf 'GLOBAL    %s lines\n' "$(lines "$GLOBAL")"; else printf 'GLOBAL    MISSING\n'; fi
  for d in "$SK"/*/; do
    [ -d "$d" ] || continue
    case "$(basename "$d")" in *.bak-*) continue ;; esac
    if [ -f "$d/SKILL.md" ]; then printf '       %-10s %s lines\n' "$(basename "$d")" "$(lines "$d/SKILL.md")"; fi
  done
}

do_verify(){
  printf '=== verify ===\n'
  if [ ! -f "$SOUL" ]; then fail 'SOUL missing'; return 1; fi
  sl=$(lines "$SOUL")
  if [ "$sl" -ne 93 ]; then fail "SOUL lines $sl != 93"; else ok "SOUL $sl lines"; fi
  pat=$(echo 'XijkuIB85LqMfOS4iXzlm5t85LqUfOWFrXzkuIN85YWrfOS5nXzljYF85Y2B5LiAfOWNgeS6jHzljYHkuIl85Y2B5ZubfOWNgeS6lCnjgIE=' | base64 -d)
  n=$(grep -cE "$pat" "$SOUL" 2>/dev/null || echo 0)
  if [ "$n" -ne 15 ]; then warn "sections $n != 15"; else ok 'sections 15'; fi
  k=$(echo '5byA5bel56ys5LiA5q2l' | base64 -d)
  if grep -q "$k" "$SOUL" 2>/dev/null; then ok 'step1 rule present'; else fail 'step1 rule missing'; fi
  miss=''
  for id in $IDS; do
    if [ ! -f "$SK/$id/SKILL.md" ]; then miss="$miss $id"; continue; fi
    r=$(echo '5b+F6aG75YWIIGZpbGVfcmVhZA==' | base64 -d)
    if ! grep -q "$r" "$SK/$id/SKILL.md" 2>/dev/null; then warn "$id lacks read-or-die line"; fi
  done
  if [ -n "$miss" ]; then fail "missing:$miss"; else ok "4/4 skills"; fi
  bad=$(ls -d "$SK"/*.bak-* 2>/dev/null | wc -l | tr -d ' ')
  if [ "$bad" -gt 0 ]; then warn "$bad legacy backups"; else ok 'no legacy backups'; fi
  echo '------------------------------------------------------------'
  echo 'IERPTkUuIEZ1bGx5IHF1aXQgTWluaXMsIHJlb3Blbiwgc2VuZDog5L2g5aW9' | base64 -d
  printf ' repo : https://github.com/%s\n' "$REPO"
  echo '------------------------------------------------------------'
  echo ' TIP: Settings - Soul shows about 2174 / 3000 tokens.'
}

do_revert(){
  printf '=== revert ===\n'
  last=$(ls -1t "$M"/memory/SOUL.md.bak-* 2>/dev/null | head -1)
  if [ -n "${last:-}" ]; then cp "$last" "$SOUL" && ok 'SOUL restored'; else warn 'no SOUL backup'; fi
  lastg=$(ls -1t "$M"/memory/GLOBAL.md.bak-* 2>/dev/null | head -1)
  if [ -n "${lastg:-}" ]; then cp "$lastg" "$GLOBAL" && ok 'GLOBAL restored'; else warn 'no GLOBAL backup'; fi
  for id in $IDS; do
    if [ -d "$BK/skills/$id" ]; then rm -rf "$SK/$id" && cp -R "$BK/skills/$id" "$SK/$id" && ok "restored $id";
    elif [ -d "$SK/$id" ]; then rm -rf "$SK/$id" && ok "removed $id"; fi
  done
  for d in "$SK"/*.bak-*; do [ -d "$d" ] && rm -rf "$d"; done
  echo 'restart the app now'
}

case "${1:-install}" in
  install) do_install ;;
  status)  do_status ;;
  verify)  do_verify ;;
  revert)  do_revert ;;
  *) printf 'usage: curl -fsSL %s | sh -s [install|status|verify|revert]\n' "https://raw.githubusercontent.com/gxxHuang/OpenMinis-pojia/main/armor-install-v2.0.sh" ;;
esac
exit 0
